/* HEXA BATTLEGROUNDS setup — PART 40 OF 55. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-bottle-0', 'bottle', 'mission', 'Bottle Shoot', 'game', 1, array['any','sports','access','gate','parking','testing','stg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":2},{"c":"blue","d":7},{"c":"green","d":0},{"c":"yellow","d":3},{"c":"purple","d":9},{"c":"orange","d":5}],"ammo":6}},"intel":{"title":"Safe order","body":"PURPLE  →  YELLOW  →  ORANGE  →  GREEN","big":true},"decoder":{"title":"Scramble rule","body":"Add 1 to every digit (9 becomes 0)."}}'::jsonb, '[{"label":"4-digit safe code","accept":["0461"]}]'::jsonb, false, 3, 200, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Purple=9 Yellow=3 Orange=5 Green=0 → +1 to each digit → 0461', null, 25, 'published'), ('mission-bottle-1', 'bottle', 'mission', 'Bottle Shoot', 'game', 1, array['any','sports','access','gate','parking','testing','stg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":2},{"c":"blue","d":3},{"c":"green","d":5},{"c":"yellow","d":8},{"c":"purple","d":0},{"c":"orange","d":9}],"ammo":6}},"intel":{"title":"Safe order","body":"PURPLE  →  YELLOW  →  ORANGE  →  RED","big":true},"decoder":{"title":"Scramble rule","body":"Read the digits in REVERSE order."}}'::jsonb, '[{"label":"4-digit safe code","accept":["2980"]}]'::jsonb, false, 3, 200, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Purple=0 Yellow=8 Orange=9 Red=2 → reversed → 2980', null, 25, 'published'), ('mission-bottle-2', 'bottle', 'mission', 'Bottle Shoot', 'game', 1, array['any','sports','access','gate','parking','testing','stg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":1},{"c":"blue","d":6},{"c":"green","d":4},{"c":"yellow","d":3},{"c":"purple","d":5},{"c":"orange","d":8}],"ammo":6}},"intel":{"title":"Safe order","body":"PURPLE  →  GREEN  →  BLUE  →  YELLOW","big":true},"decoder":{"title":"Scramble rule","body":"Subtract each digit from 9."}}'::jsonb, '[{"label":"4-digit safe code","accept":["4536"]}]'::jsonb, false, 3, 200, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Purple=5 Green=4 Blue=6 Yellow=3 → 9 minus each digit → 4536', null, 25, 'published'), ('mission-bottle-3', 'bottle', 'mission', 'Bottle Shoot', 'game', 1, array['any','sports','access','gate','parking','testing','stg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":9},{"c":"blue","d":7},{"c":"green","d":0},{"c":"yellow","d":8},{"c":"purple","d":3},{"c":"orange","d":1}],"ammo":6}},"intel":{"title":"Safe order","body":"ORANGE  →  GREEN  →  RED  →  PURPLE","big":true},"decoder":{"title":"Scramble rule","body":"Keep the digits exactly as they are — no change."}}'::jsonb, '[{"label":"4-digit safe code","accept":["1093"]}]'::jsonb, false, 3, 200, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Orange=1 Green=0 Red=9 Purple=3 → unchanged → 1093', null, 25, 'published'), ('mission-bottle-4', 'bottle', 'mission', 'Bottle Shoot', 'game', 1, array['any','sports','access','gate','parking','testing','stg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":9},{"c":"blue","d":2},{"c":"green","d":7},{"c":"yellow","d":6},{"c":"purple","d":8},{"c":"orange","d":4}],"ammo":6}},"intel":{"title":"Safe order","body":"YELLOW  →  ORANGE  →  GREEN  →  RED","big":true},"decoder":{"title":"Scramble rule","body":"Swap the first two digits and the last two digits."}}'::jsonb, '[{"label":"4-digit safe code","accept":["4697"]}]'::jsonb, false, 3, 200, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Yellow=6 Orange=4 Green=7 Red=9 → pairs swapped → 4697', null, 25, 'published'), ('mission-bottle-5', 'bottle', 'mission', 'Bottle Shoot', 'game', 1, array['any','sports','access','gate','parking','testing','stg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":0},{"c":"blue","d":2},{"c":"green","d":5},{"c":"yellow","d":8},{"c":"purple","d":1},{"c":"orange","d":3}],"ammo":6}},"intel":{"title":"Safe order","body":"BLUE  →  ORANGE  →  PURPLE  →  RED","big":true},"decoder":{"title":"Scramble rule","body":"Add 2 to every digit and keep only the last digit (9 → 1)."}}'::jsonb, '[{"label":"4-digit safe code","accept":["4532"]}]'::jsonb, false, 3, 200, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Blue=2 Orange=3 Purple=1 Red=0 → +2 to each digit → 4532', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, rel